const body = $input.item.json.body || $input.item.json;

const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const telefono = message.from;
const texto = message.text?.body || '';
const messageId = message.id;
const timestamp = message.timestamp;
const nombreContacto = value?.contacts?.[0]?.profile?.name || '';

// FIX: Deduplicación — Meta envía el mismo webhook dos veces
// Usamos static data para recordar messageIds procesados en los últimos 60s
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessageIds) staticData.seenMessageIds = {};

const now = Date.now();
// Limpiar entradas viejas (> 60 segundos)
Object.keys(staticData.seenMessageIds).forEach(id => {
  if (now - staticData.seenMessageIds[id] > 60000) delete staticData.seenMessageIds[id];
});

if (staticData.seenMessageIds[messageId]) {
  // Mensaje duplicado — ignorar
  return [{ json: { skip: true, skipReason: 'duplicate_messageId' } }];
}
staticData.seenMessageIds[messageId] = now;

return [{
  json: {
    telefono,
    texto,
    messageId,
    timestamp,
    nombreContacto,
    skip: false
  }
}];

const msgData = $('🔧 Extraer Mensaje y Teléfono').item.json;
const configData = $('📊 Obtener Config Empresa').item.json;
const waConfigData = $('⚙️ Obtener WA Config').item.json;
const leadData = $('📋 Buscar Lead Existente').item.json;

const config = configData.records?.[0]?.fields || {};
const waConfig = waConfigData.records?.[0]?.fields || {};
const emailVendedor = config.WA_Email_Vendedor || 'risosadmi@gmail.com';
const descripcion = config['descripción_corta'] || 'Embalajes de madera a medida en Miami, FL. Cajones con ISPM-15.';
const followup24 = waConfig.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || '';

const leadExistente = leadData.records?.[0];
const leadId = leadExistente?.id || null;
const leadFields = leadExistente?.fields || {};

// === CARGAR ESTADO DESDE AIRTABLE ===
let datosRecolectados = {
  producto: leadFields.Articulo || null,
  medidas: leadFields['Medidas y Peso'] || null,
  fecha: null,
  tipo_cajon: null,
  proteccion_extra: null,
  direccion: null,
  correo_contacto: null,
  nombre_cliente: leadFields.Nombre_Contacto || null
};

let notasOriginal = {};
try {
  const notas = leadFields.Notas || '';
  if (notas && notas.trim().startsWith('{')) {
    const stored = JSON.parse(notas);
    notasOriginal = stored;
    if (stored.tipo_cajon) datosRecolectados.tipo_cajon = stored.tipo_cajon;
    if (stored.direccion) datosRecolectados.direccion = stored.direccion;
    if (stored.correo_contacto) datosRecolectados.correo_contacto = stored.correo_contacto;
    if (stored.nombre_cliente && !datosRecolectados.nombre_cliente) datosRecolectados.nombre_cliente = stored.nombre_cliente;
    if (stored.proteccion_extra !== null && stored.proteccion_extra !== undefined) datosRecolectados.proteccion_extra = stored.proteccion_extra;
    if (stored.fecha) datosRecolectados.fecha = stored.fecha;
  }
} catch(e) {}

const r3 = leadFields['¿Protección adicional?'] || '';
if (r3 === 'true') datosRecolectados.proteccion_extra = true;
else if (r3 === 'false') datosRecolectados.proteccion_extra = false;

const estado = leadFields.Estado || 'Nuevo';
const cotizacionEnviada = notasOriginal.cotizacion_enviada === true || ['Vendedor notificado', 'Cotizacion_Enviada'].includes(estado);
const historial = leadFields.Historial_Mensajes || '';
const esNuevo = !leadId;

// Catálogo de productos
const productosData = $('📦 Obtener Productos').item.json;
const productosRaw = productosData.records || [];
const catalogoProductos = productosRaw.map(r => {
  const f = r.fields;
  return Object.entries(f).find(([k]) => k.includes('Nombre de Servicio'))?.[1] || '';
}).filter(l => l.length > 2).join(', ');

// RAG Pinecone (opcional)
let catalogoFinal = catalogoProductos;
try {
  const pineconeData = $('🔍 Contexto CE (Pinecone)').item.json;
  const chunks = (pineconeData.matches || [])
    .filter(m => (m.score || 0) > 0.75)
    .map(m => m.metadata?.text || '')
    .filter(t => t.length > 20).slice(0, 3).join('\n');
  if (chunks) catalogoFinal = chunks;
} catch(e) {}

const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes' : 'buenas noches';

const texto = (msgData.texto || '').trim();
const textoLower = texto.toLowerCase();
const hasDigits = /\d/.test(texto);
const isGreeting = /^(hola\b|hi\b|buenas\b|buenos\b|hey\b|good\s|morning|afternoon|evening|hello\b)/i.test(texto);

// Palabras que indican que el mensaje NO es un nombre
const isServiceMention = /\b(cotiz|lavadora|refrigerador|mueble|nevera|estufa|máquina|machine|embalaje|caja|cajón|crate|pack|madera|necesito|quiero|quisiera|me gustaría|precio|medid|pulgad)\b/i.test(texto);

// =====================================================================
// MÁQUINA DE ESTADO EN CÓDIGO
// =====================================================================
const cleanCheck = v => {
  if (typeof v === 'boolean') return v;
  if (!v || v === 'desconocido' || v === 'null' || v === 'undefined') return null;
  return v;
};

const calcProximoPaso = d => {
  if (cotizacionEnviada) return 'POST_COTIZACION';
  if (esNuevo) return 'PRIMER_CONTACTO';
  if (!cleanCheck(d.nombre_cliente)) return 'PEDIR_NOMBRE';
  if (!cleanCheck(d.producto)) return 'PEDIR_PRODUCTO';
  if (!cleanCheck(d.medidas)) return 'PEDIR_MEDIDAS';
  if (!cleanCheck(d.tipo_cajon)) return 'PEDIR_TIPO_CAJON';
  if (d.proteccion_extra === null || d.proteccion_extra === undefined) return 'PEDIR_PROTECCION';
  if (!cleanCheck(d.fecha)) return 'PEDIR_FECHA';
  return 'LISTO_PARA_COTIZAR';
};

let proximoPaso = calcProximoPaso(datosRecolectados);
const nombreAntesMensaje = datosRecolectados.nombre_cliente;

// =====================================================================
// EXTRACCIÓN DE DATOS DEL MENSAJE ACTUAL (basado en paso esperado)
// =====================================================================
if (texto.length > 0) {

  // NOMBRE: solo extraer si parece realmente un nombre (1-3 palabras, sin menciones de servicio)
  if ((proximoPaso === 'PRIMER_CONTACTO' || proximoPaso === 'PEDIR_NOMBRE') && !isGreeting && !isServiceMention) {
    const palabras = texto.split(/\s+/);
    if (palabras.length <= 4 && !hasDigits) {
      datosRecolectados.nombre_cliente = texto;
    }
  }

  // PRODUCTO: cualquier mensaje que no sea saludo y esté en el paso correcto
  if (proximoPaso === 'PEDIR_PRODUCTO' && !isGreeting) {
    datosRecolectados.producto = texto;
  }

  // MEDIDAS: solo si hay dígitos
  if (proximoPaso === 'PEDIR_MEDIDAS' && hasDigits) {
    datosRecolectados.medidas = texto;
  }

  // TIPO CAJÓN: confirmar o especificar
  if (proximoPaso === 'PEDIR_TIPO_CAJON') {
    const confirma = /^(si\b|sí\b|yes\b|dale|claro|ok\b|bien\b|perfecto|adelante|sure\b|de acuerdo|sounds|me parece|sisi)/i.test(textoLower);
    if (/jaula/i.test(texto)) datosRecolectados.tipo_cajon = 'jaulas';
    else if (/palet|pallet/i.test(texto)) datosRecolectados.tipo_cajon = 'palets_medida';
    else if (/cuna/i.test(texto)) datosRecolectados.tipo_cajon = 'cunas';
    else if (/plataforma/i.test(texto)) datosRecolectados.tipo_cajon = 'plataformas_contenedor';
    else if (/feria/i.test(texto)) datosRecolectados.tipo_cajon = 'embalaje_ferias';
    else if (confirma || /cajon|cajón|cerrado|crate|box/i.test(texto)) datosRecolectados.tipo_cajon = 'cajones_cerrados';
  }

  // PROTECCIÓN: sí/no explícito
  if (proximoPaso === 'PEDIR_PROTECCION') {
    if (/\b(si\b|sí\b|yes\b|dale|claro|ok\b|quiero|foam|burbuja|esquinera|por favor|please|add|agrega|agregar|sisi)\b/i.test(textoLower)) {
      datosRecolectados.proteccion_extra = true;
    } else if (/^(no\b|nope\b|sin |no gracias|no quiero|no thanks|don't|dont|skip|sin protec)/i.test(textoLower)) {
      datosRecolectados.proteccion_extra = false;
    }
  }

  // FECHA: cualquier referencia temporal
  if (proximoPaso === 'PEDIR_FECHA') {
    const hasFechaRef = hasDigits ||
      /\b(hoy|mañana|lunes|martes|miércoles|miercoles|jueves|viernes|sábado|sabado|domingo|monday|tuesday|wednesday|thursday|friday|saturday|sunday|urgente|asap|lo antes|inmediato|semana|semanas|mes|meses|enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre|january|february|march|april|june|july|august|september|october|november|december|primero|próximo|proximo|siguiente|días|dias|horas)\b/i.test(texto);
    if (hasFechaRef) datosRecolectados.fecha = texto;
  }

  // EMAIL: extraer si aparece en cualquier mensaje
  if (!datosRecolectados.correo_contacto && texto.includes('@')) {
    const emailMatch = texto.match(/[\w.+-]+@[\w-]+\.[\w.]+/);
    if (emailMatch) datosRecolectados.correo_contacto = emailMatch[0];
  }
}

// Recalcular después de extracción
proximoPaso = calcProximoPaso(datosRecolectados);
const nombreRecienExtractado = !nombreAntesMensaje && datosRecolectados.nombre_cliente;

// DETECCIÓN DE CIERRE / DESPEDIDA (post-cotización o en cualquier momento si es señal fuerte)
const isCierreSena = /\b(muchas gracias|thank you very|thanks a lot|that'?s? all|eso es todo|ya está|nada más|nada mas|hasta luego|bye\b|adiós|adios|hasta pronto|me queda claro|solo quería saber|ya tengo lo|con eso basta|no necesito más|ya era todo)\b/i.test(textoLower);
if (isCierreSena && (cotizacionEnviada || proximoPaso === 'LISTO_PARA_COTIZAR' || proximoPaso === 'POST_COTIZACION')) {
  proximoPaso = 'DESPEDIDA';
}

// =====================================================================
// DIMENSIONES
// =====================================================================
let dimensiones = { largo: null, ancho: null, alto: null };
const medidasStr = datosRecolectados.medidas || '';
if (medidasStr) {
  const dimMatch = medidasStr.match(/(\d+(?:\.\d+)?)\s*[x*×]\s*(\d+(?:\.\d+)?)\s*[x*×]\s*(\d+(?:\.\d+)?)/i);
  if (dimMatch) {
    dimensiones = { largo: parseFloat(dimMatch[1]), ancho: parseFloat(dimMatch[2]), alto: parseFloat(dimMatch[3]) };
  } else {
    const nums = medidasStr.match(/\d+(?:\.\d+)?/g);
    if (nums && nums.length >= 3) dimensiones = { largo: parseFloat(nums[0]), ancho: parseFloat(nums[1]), alto: parseFloat(nums[2]) };
  }
}

const tipoCajaApiMap = { cajones_cerrados:'cajones_cerrados', jaulas:'jaulas', palets_medida:'palets_medida', cunas:'cunas', plataformas_contenedor:'plataformas_contenedor', embalaje_ferias:'embalaje_ferias', mayor:'mayor' };
const tipoCajaApi = tipoCajaApiMap[datosRecolectados.tipo_cajon] || null;
const todosRecolectados = proximoPaso === 'LISTO_PARA_COTIZAR';

// =====================================================================
// PROMPT SIMPLIFICADO PARA LA IA
// La IA SOLO genera el texto de respuesta — NO maneja estado
// =====================================================================
const nombre = datosRecolectados.nombre_cliente || '';
const producto = datosRecolectados.producto || '';
const medidas = datosRecolectados.medidas || '';
const saludo = saludoHora.charAt(0).toUpperCase() + saludoHora.slice(1);

let tareaIA;
if (proximoPaso === 'PRIMER_CONTACTO') {
  // Mensaje hardcodeado — la IA debe copiarlo exactamente
  tareaIA = `PRIMER CONTACTO. Escribe EXACTAMENTE este texto (no cambies nada, no agregues nada):\n"${saludo}, soy Alex, el asistente de Crating Express. ¿Con quién tengo el gusto?"`;
} else if (proximoPaso === 'PEDIR_NOMBRE') {
  tareaIA = `El cliente no ha dicho su nombre todavía. Pregúntale amigablemente: "¿Con quién tengo el gusto?"`;
} else if (proximoPaso === 'PEDIR_PRODUCTO') {
  tareaIA = nombreRecienExtractado
    ? `El cliente acaba de dar su nombre: "${nombre}". Di EXACTAMENTE: "¡Mucho gusto, ${nombre}! ¿Qué artículo necesitas embalar?"`
    : `Saluda a ${nombre} y pregunta qué artículo necesita embalar.`;
} else if (proximoPaso === 'PEDIR_MEDIDAS') {
  tareaIA = `Artículo confirmado: "${producto}". Pide las medidas en pulgadas: Largo × Ancho × Alto, y el peso aproximado en libras.`;
} else if (proximoPaso === 'PEDIR_TIPO_CAJON') {
  tareaIA = `Artículo: "${producto}", medidas: ${medidas}. Recomienda cajón cerrado para máxima protección con ISPM-15 y pregunta si está bien. Una sola oración.`;
} else if (proximoPaso === 'PEDIR_PROTECCION') {
  tareaIA = `Tipo de cajón confirmado. Pregunta si el cliente desea protección interior (foam, burbuja o esquineras). Aclara que tiene costo adicional. Solo esa pregunta, nada más.`;
} else if (proximoPaso === 'PEDIR_FECHA') {
  tareaIA = `Ya tienes producto, medidas, tipo de cajón y protección. Pregunta SOLO: ¿para cuándo necesitas el embalaje listo?`;
} else if (proximoPaso === 'LISTO_PARA_COTIZAR') {
  tareaIA = `Todos los datos confirmados. Genera un mensaje MUY breve diciendo que calcularás el estimado para "${producto}". NO menciones precios — el sistema los calculará.`;
} else if (proximoPaso === 'POST_COTIZACION') {
  tareaIA = datosRecolectados.correo_contacto
    ? `Ya tienes el correo "${datosRecolectados.correo_contacto}". Confirma que un especialista de Crating Express se pondrá en contacto y despídete cordialmente.`
    : `Se envió la cotización. Pregunta el correo electrónico del cliente para que un especialista de Crating Express pueda contactarle.`;
} else if (proximoPaso === 'DESPEDIDA') {
  tareaIA = `El cliente está terminando la conversación. Despídete cordialmente, agradece su contacto y menciona que Crating Express está disponible cuando lo necesite.`;
} else {
  tareaIA = `Responde al mensaje del cliente de forma natural y profesional.`;
}

// Sistema: conciso, idioma del cliente, SIN inventar precios
const sistemaIA = `Eres Alex, asistente de Crating Express en Miami. Embalajes de madera a medida, ISPM-15 incluido. Responde en el idioma del cliente (español o inglés). Sé profesional, amigable y MUY conciso — máximo 2 oraciones. Ejecuta ÚNICAMENTE la tarea indicada. NUNCA menciones precios ni costos (el sistema los calcula automáticamente). NUNCA hagas preguntas extra.`;
const usuarioIA = `${tareaIA}\n\nMensaje del cliente: "${texto}"`;

return [{ json: {
  telefono: msgData.telefono,
  texto,
  nombreContacto: msgData.nombreContacto || '',
  emailVendedor,
  descripcion,
  followup24,
  followup72,
  leadId,
  estado,
  historial,
  datosRecolectados,
  cotizacionEnviada,
  esNuevo,
  saludoHora,
  catalogoProductos,
  proximoPaso,
  dimensiones,
  tipoCajaApi,
  todosRecolectados,
  sistemaIA,
  usuarioIA
} }];

