const ctx = $('🔧 Preparar Contexto IA').item.json;
const proximoPaso = ctx.proximoPaso;
const d = ctx.datosRecolectados;
const saludo = ctx.saludoHora.charAt(0).toUpperCase() + ctx.saludoHora.slice(1);
const nombre = d.nombre_cliente || '';

let mensaje;
if (proximoPaso === 'PRIMER_CONTACTO') {
  mensaje = `${saludo}, soy Alex, el asistente de Crating Express. ¿Con quién tengo el gusto?`;
} else if (proximoPaso === 'PEDIR_NOMBRE') {
  mensaje = '¿Con quién tengo el gusto?';
} else if (proximoPaso === 'PEDIR_PRODUCTO') {
  mensaje = nombre ? `¡Mucho gusto, ${nombre}! ¿Qué artículo necesitas embalar?` : '¿Qué artículo necesitas embalar?';
} else if (proximoPaso === 'PEDIR_MEDIDAS') {
