const parsear = $('🔍 Parsear Respuesta IA').item.json;
const cotizacion = $input.item.json;

const precio = cotizacion?.data?.precio_total;

let mensajeExtra = '';
if (precio) {  // BUG4: API no devuelve campo success
  mensajeExtra = `\n\n💵 *Precio estimado: $${precio} USD*\n_Este es un estimado basado en las dimensiones indicadas. El precio final puede variar según detalles adicionales._\n\n¿Le gustaría que un especialista de Crating Express lo contacte para una cotización formal y precio definitivo?\n\nTambién puede cotizar en línea aquí: https://cratingcotiza.mdarthurdigital.com/cotizar-caja`;
} else {
  mensajeExtra = `\n\nPuede solicitar una cotización formal en: https://cratingcotiza.mdarthurdigital.com/cotizar-caja\no escribirnos a cratingexpress01@gmail.com`;
}

return [{
  json: {
    ...parsear,
    mensaje: (parsear.mensaje || '') + mensajeExtra,
    cotizador_enviado: true,
    guardar_cotizacion_flag: true,
    nuevoEstado: precio ? 'Calificado' : parsear.nuevoEstado  // BUG4: API no tiene campo success
  }
}];

const body = $input.item.json.body || $input.item.json;

const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const telefono = message.from;
const texto = message.text?.body || '';
const messageId = message.id;
const timestamp = message.timestamp;
const nombreContacto = value?.contacts?.[0]?.profile?.name || '';

// FIX: Deduplicación — Meta envía el mismo webhook dos veces
// Usamos static data para recordar messageIds procesados en los últimos 60s
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessageIds) staticData.seenMessageIds = {};

const now = Date.now();
// Limpiar entradas viejas (> 60 segundos)
Object.keys(staticData.seenMessageIds).forEach(id => {
  if (now - staticData.seenMessageIds[id] > 60000) delete staticData.seenMessageIds[id];
});

if (staticData.seenMessageIds[messageId]) {
  // Mensaje duplicado — ignorar
  return [{ json: { skip: true, skipReason: 'duplicate_messageId' } }];
}
staticData.seenMessageIds[messageId] = now;

return [{
  json: {
    telefono,
    texto,
    messageId,
    timestamp,
    nombreContacto,
    skip: false
  }
}];

const msgData = $('🔧 Extraer Mensaje y Teléfono').item.json;
const configData = $('📊 Obtener Config Empresa').item.json;
const waConfigData = $('⚙️ Obtener WA Config').item.json;
const leadData = $('📋 Buscar Lead Existente').item.json;

const config = configData.records?.[0]?.fields || {};
const waConfig = waConfigData.records?.[0]?.fields || {};
const bienvenida = waConfig.WA_Mensaje_Bienvenida || config.WA_Mensaje_Bienvenida || 'Hola 👋 buen día, soy el asistente de Crating Express en Miami. ¿En qué te puedo ayudar?';
const emailVendedor = config.WA_Email_Vendedor || 'risosadmi@gmail.com';
const descripcion = config['descripción_corta'] || 'Embalajes de madera a medida en Miami, FL. Cajones y cajas con certificación ISPM-15.';
const instruccionesIA = waConfig.Instrucciones_IA || config.Instrucciones_IA || '';
const promptTemplate = waConfig.Prompt_Sistema || config.Prompt_Sistema || '';
const followup24 = waConfig.WA_FollowUp_24h || config.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || config.WA_FollowUp_72h || '';

const leadExistente = leadData.records?.[0];
const leadId = leadExistente?.id || null;
const leadFields = leadExistente?.fields || {};

// Read from Respuesta_1/2/3 fields (reliable individual fields)
let datosRecolectados = {
  producto: leadFields.Articulo || null,
  medidas: leadFields['Medidas y Peso'] || null,
  fecha: null,
  tipo_cajon: null,
  proteccion_extra: null,
  direccion: null,
  correo_contacto: null,
  nombre_cliente: null
};

// Try to supplement tipo_cajon and proteccion_extra from Notas
try {
  const notas = leadFields.Notas || '';
  if (notas && notas.trim().startsWith('{')) {
    const stored = JSON.parse(notas);
    if (stored.tipo_cajon) datosRecolectados.tipo_cajon = stored.tipo_cajon;
    if (stored.direccion) datosRecolectados.direccion = stored.direccion;
    if (stored.correo_contacto) datosRecolectados.correo_contacto = stored.correo_contacto;
    if (stored.nombre_cliente) datosRecolectados.nombre_cliente = stored.nombre_cliente;
    // BUG1: Use explicit null check so false is preserved
    if (stored.proteccion_extra !== null && stored.proteccion_extra !== undefined) {
      datosRecolectados.proteccion_extra = stored.proteccion_extra;
    }
    // BUG2: Load fecha from Notas
    if (stored.fecha) datosRecolectados.fecha = stored.fecha;
  }
} catch(e) {}

// BUG2: Load proteccion_extra from Respuesta_3 (new format: 'true'/'false' string)
const r3 = leadFields['¿Protección adicional?'] || '';
if (r3 === 'true') datosRecolectados.proteccion_extra = true;
else if (r3 === 'false') datosRecolectados.proteccion_extra = false;
// Fallback: if Notas already had proteccion (old format), prefer that
// (already loaded above in try block with explicit null check)


// Also read Nombre_Contacto from the lead record
if (!datosRecolectados.nombre_cliente && leadFields.Nombre_Contacto) {
  datosRecolectados.nombre_cliente = leadFields.Nombre_Contacto;
}

// Parse Notas JSON for stored flags
const notasObj = (() => { try { const n = leadFields.Notas || '{}'; return n.trim().startsWith('{') ? JSON.parse(n) : {}; } catch(e) { return {}; } })();
const estado = leadFields.Estado || 'Nuevo';
const cotizacionEnviada = notasObj.cotizacion_enviada === true || ['Lead Caliente', 'Cotizacion_Enviada', 'Calificado'].includes(estado);
const historial = leadFields.Historial_Mensajes || '';
const esNuevo = !leadId;


// Read products catalog from Airtable
const productosData = $('📦 Obtener Productos').item.json;
const productosRaw = productosData.records || [];
const catalogoProductos = productosRaw.map(r => {
  const f = r.fields;
  const nombre = Object.entries(f).find(([k]) => k.includes('Nombre de Servicio'))?.[1] || '';
  const cuando = (f['cuando_recomendar'] || '').split('\n')[0].trim();
  const noUsar = (f['cuando_no_recomendar'] || '').split('\n')[0].trim();
  return `${nombre}: ${cuando}${noUsar ? '. NO: ' + noUsar : ''}`;
}).filter(l => l.length > 2).join('\n');

// RAG: recuperar chunks de CE desde Pinecone
let catalogoFinal = catalogoProductos;
try {
  const pineconeData = $('🔍 Contexto CE (Pinecone)').item.json;
  const matches = pineconeData.matches || [];
  const chunks = matches
    .filter(m => (m.score || 0) > 0.75)
    .map(m => m.metadata?.text || m.metadata?._node_content || '')
    .filter(t => t.length > 20)
    .slice(0, 5)
    .join('\n---\n');
  if (chunks) catalogoFinal = chunks;
} catch(e) { catalogoFinal = catalogoProductos; }

// Build final prompt substituting dynamic values
const promptSistema = promptTemplate
  .replace('{{CATALOGO}}', catalogoFinal)
  .replace('{{INSTRUCCIONES}}', instruccionesIA ? 'Instrucciones adicionales: ' + instruccionesIA : '')
  .trim();

// Greeting based on Miami time (UTC-4 EDT)
const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes'
  : 'buenas noches';

// Calculate next pending step (deterministic — model just follows this)
const cleanCheck = v => {
  if (typeof v === 'boolean') return v;
  if (!v || v === 'desconocido' || v === 'null' || v === 'undefined') return null;
  return v;
};
const dR = datosRecolectados;
let proximoPaso;
if (cotizacionEnviada) {
  proximoPaso = 'POST_COTIZACION';
} else if (esNuevo) {
  proximoPaso = 'PRIMER_CONTACTO';
} else if (!cleanCheck(dR.nombre_cliente)) {
  proximoPaso = 'PEDIR_NOMBRE';
} else if (!cleanCheck(dR.producto)) {
  proximoPaso = 'PEDIR_PRODUCTO';
} else if (!cleanCheck(dR.medidas)) {
  proximoPaso = 'PEDIR_MEDIDAS';
} else if (!cleanCheck(dR.tipo_cajon)) {
  proximoPaso = 'PEDIR_TIPO_CAJON';
} else if (dR.proteccion_extra === null || dR.proteccion_extra === undefined || dR.proteccion_extra === 'desconocido') {
  proximoPaso = 'PEDIR_PROTECCION';
} else if (!cleanCheck(dR.fecha)) {
  proximoPaso = 'PEDIR_FECHA';
} else {
  proximoPaso = 'LISTO_PARA_COTIZAR';
}




return [{ json: {
  telefono: msgData.telefono,
  texto: msgData.texto,
  nombreContacto: msgData.nombreContacto || '',
  emailVendedor,
  descripcion,
  instruccionesIA,
  bienvenida,
  followup24,
  followup72,
  leadId,
  estado,
  historial,
  datosRecolectados,
  cotizacionEnviada,
  esNuevo,
  saludoHora,
  catalogoProductos,
  promptSistema,
  proximoPaso
} }];

