// Handle OpenAI-format (Groq/DeepSeek choices) or Contingency (direct object)
const raw = $input.item.json;
let aiResponse;
if (raw._contingencia) {
  aiResponse = JSON.stringify(raw);
} else {
  aiResponse = raw.choices?.[0]?.message?.content || '{}';
}

let result;
try { result = JSON.parse(aiResponse); }
catch(e) {
  result = {
    mensaje: 'Gracias por tu mensaje. Te ayudaremos con tu cotización.',
    datos_actualizados: {},
    dimensiones: { largo: null, ancho: null, alto: null },
    tipo_caja_api: null,
    todos_recolectados: false,
    cotizador_enviado: false,
    clasificacion: null,
    resumen_lead: ''
  };
}

const ctx = $('🔧 Preparar Contexto IA').item.json;
const datosAnt = ctx.datosRecolectados || {};
const datosNuevos = result.datos_actualizados || {};

// FIX: clean() preserves boolean false — false is a valid answer ("no quiero protección")
const clean = (v) => {
  if (typeof v === 'boolean') return v; // false = respuesta válida, NO convertir a null
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'string' && ['desconocido', 'null', 'undefined', 'no sé', 'no se', 'n/a'].includes(v.toLowerCase().trim())) return null;
  return v;
};

// FIX: merge() usa null-check explícito en vez de ||
// || convierte false a null. merge() preserva false correctamente.
const merge = (a, b) => {
  const ca = clean(a);
  const cb = clean(b);
  if (ca !== null && ca !== undefined) return ca;
  if (cb !== null && cb !== undefined) return cb;
  return null;
};

const datosMerged = {
  producto:        merge(datosNuevos.producto,        datosAnt.producto),
  medidas:         merge(datosNuevos.medidas,         datosAnt.medidas),
  fecha:           merge(datosNuevos.fecha,            datosAnt.fecha),
  tipo_cajon:      merge(datosNuevos.tipo_cajon,      datosAnt.tipo_cajon),
  proteccion_extra: merge(datosNuevos.proteccion_extra, datosAnt.proteccion_extra),
  direccion:       merge(datosNuevos.direccion,       datosAnt.direccion),
  correo_contacto: merge(datosNuevos.correo_contacto, datosAnt.correo_contacto),
  nombre_cliente:  merge(datosNuevos.nombre_cliente,  datosAnt.nombre_cliente),
};

// Dimensiones y tipo_caja_api del modelo
const dims = result.dimensiones || { largo: null, ancho: null, alto: null };
const tipoCajaApi = result.tipo_caja_api || null;

// todos_recolectados — validación código
let todosRecolectados = result.todos_recolectados === true;
if (todosRecolectados && !merge(datosNuevos.tipo_cajon, datosAnt.tipo_cajon)) {
  todosRecolectados = false;
}
// proteccion_extra confirmada = fue contestada explícitamente (true o false)
// Con el fix de clean(), false ya no se convierte a null — esto funciona correctamente
const proteccionConfirmada = datosMerged.proteccion_extra !== null && datosMerged.proteccion_extra !== undefined;
if (todosRecolectados && !proteccionConfirmada) {
  todosRecolectados = false;
}
// BUG7: fecha is required to cotizar
if (todosRecolectados && !datosMerged.fecha) {
  todosRecolectados = false;
}
// Guard: medidas must contain actual numbers (not "me parece bien" etc.)
if (todosRecolectados && datosMerged.medidas && !/\d/.test(datosMerged.medidas)) {
  todosRecolectados = false;
  datosMerged.medidas = null; // reset invalid medidas
}

// FIX: Dimension extraction fallback — parse numbers from medidas text if model didn't extract them
if (todosRecolectados && datosMerged.medidas && (!dims.largo || !dims.ancho || !dims.alto)) {
  const nums = datosMerged.medidas.match(/\\d+(\\.\\d+)?/g);
  if (nums && nums.length >= 3) {
    dims.largo = parseFloat(nums[0]);
    dims.alto  = parseFloat(nums[1]);
    dims.ancho = parseFloat(nums[2]);
  }
}

// Estado válido Airtable
let nuevoEstado = ctx.estado;
if (result.cotizador_enviado && result.clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (result.cotizador_enviado) nuevoEstado = 'Calificado';
else if (result.clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (result.clasificacion) nuevoEstado = 'Calificado';
else if (!ctx.leadId || nuevoEstado === 'Nuevo') nuevoEstado = 'En calificación';

const ts = new Date().toISOString();
const nuevoHistorial = (ctx.historial ? ctx.historial + '\n' : '') +
  `[${ts}] Cliente: ${ctx.texto}\n[${ts}] Bot: ${result.mensaje || ''}`;

// Guard: si el modelo saltó a cotizar sin tener todos los datos
const modelWantedToCotizar = result.todos_recolectados === true && !todosRecolectados;
let mensajeFinal = result.mensaje || '';
if (modelWantedToCotizar) {
  if (!datosMerged.medidas) {
    mensajeFinal = '¿Podrías darme las medidas del artículo en pulgadas? Necesito largo × ancho × alto y el peso aproximado en libras.';
  } else if (!datosMerged.fecha) {
    mensajeFinal = '¿Para cuándo necesitas el embalaje listo?';
  } else if (datosMerged.proteccion_extra === null || datosMerged.proteccion_extra === undefined) {
    mensajeFinal = '¿Te gustaría agregar protección interior (foam, burbuja o esquineras)? Tiene un costo adicional pero protege mejor el artículo.';
  }
}

return [{ json: {
  ...ctx,
  mensaje: mensajeFinal,
  mensajeRespuesta: mensajeFinal,
  datosRecolectados: datosMerged,
  todos_recolectados: todosRecolectados,
  todosRecolectados: todosRecolectados,
  dimensiones: dims,
  tipo_caja_api: tipoCajaApi,
  cotizador_enviado: result.cotizador_enviado || false,
  cotizadorEnviado: result.cotizador_enviado || false,
  clasificacion: result.clasificacion || null,
  resumenLead: result.resumen_lead || '',
  nuevoEstado,
  nuevoHistorial
} }];

